import React from "react";
import {
  FaCode,
  FaAward,
  FaLaptopCode,
  FaUsers,
  FaComments,
  FaLightbulb,
  FaCogs,
  FaUsersCog,
  FaClock,
  FaBrain,
  FaExternalLinkAlt
} from "react-icons/fa";

const Skills = () => {
  return (
    <section className="skills-page">

